Rules.InvariantScript:
UpdateContext({ showSpinner: true });

// 1. Build the collection. 
// We include the "ID" to tell Patch whether to Update (ID exists) or Create (ID is blank).
ClearCollect(
    colSafeUpdates,
    ForAll(
        [@PowerBIIntegration].Data As _item,
        With(
            {
                // Try to find the existing record in SQL
                _existingRecord: LookUp(
                    vs_review_workflow_data,
                    record_id = _item.record_id
                )
            },
            {
                // SYSTEM ID: If found, use it (Update). If blank, leave blank (Create).
                ID: _existingRecord.ID, 

                // --- FIELDS TO UPDATE (From Bulk Edit Screen) ---
                Status: "Awaiting Medical Review",
                scientific_reviewer_comment: txt_sci_reviewer_1.Text,
                scientific_review_modified_by: User().FullName,
                scientific_review_modified_on: Now(),
                bulk_update: "Yes",
                Role: First([@PowerBIIntegration].Data).Role,

                // --- MANDATORY FIELDS FOR NEW RECORDS ---
                // These are required if we are creating a row. 
                // For updates, passing the same value is harmless.
                record_id: _item.record_id,
                participant_id: _item.participant_id,
                project_code: Value(_item.project_code),
                visit_date: DateTimeValue(_item.visit_date)

                // --- OMITTED FIELDS (To Protect Data) ---
                // We deliberately exclude 'medical_query', 'data_management_query', etc.
                // - For Updates: SQL keeps the existing values.
                // - For Creates: SQL sets them to NULL (correct for a fresh review).
            }
        )
    )
);

// 2. Safety Check: Ensure we don't submit empty rows
RemoveIf(colSafeUpdates, IsBlank(record_id));

// 3. Single Patch to Database (Handles both Updates and Creates)
If(
    CountRows(colSafeUpdates) > 0,
    Patch(
        vs_review_workflow_data,
        colSafeUpdates
    );
    Notify(
        "Success! " & CountRows(PowerBIIntegration.Data) & " records were updated.
Continue bulk editing until all records are cleared from the screen.",
        NotificationType.Success
    ),
    Notify(
        "No records to update.",
        NotificationType.Warning
    )
);

// 4. Audit Logging
ClearCollect(
    colAuditPayload,
    ForAll(
        [@PowerBIIntegration].Data As _item,
        {
            Status: "Awaiting Medical Review",
            record_id: _item.record_id,
            visit_date: DateTimeValue(_item.visit_date),
            participant_id: _item.participant_id,
            project_code: Value(_item.project_code),
            Role: First([@PowerBIIntegration].Data).Role,
            scientific_reviewer_comment: txt_sci_reviewer_1.Text,
            scientific_review_modified_by: User().FullName,
            scientific_review_modified_on: Now(),
            bulk_update: "Yes"
        }
    )
);

// 5. Trigger Flow
Collect(
    vs_review_workflow_data_audit,
    colAuditPayload
);

Set(
    varFlowResult, 
    'Button->InvokeanHTTPrequest'.Run()
);

If(
    varFlowResult.datasetrefreshstatus = "Completed",
    Notify("Flow processed successfully.", NotificationType.Success);
    PowerBIIntegration.Refresh();
    Reset(txt_med_reviewer_1);
    Reset(txt_sci_reviewer_1),
    Notify("Update Failed or Flow Error.", NotificationType.Error)
);
Navigate('Scientific Reviewer',BorderStyle.None);
UpdateContext({ showSpinner: false });
